    # Grab the enemy if it's in front and the clamp is open
    if enemy.x < 0 and abs(enemy.y) < 0.5 and me.weapons["front"]["state"] == "open" and me.weapons["front"]["cooldown"] == 0:
        return grab("front")
    # Release the enemy if it's not in front anymore
    elif me.weapons["front"]["state"] == "holding" and (enemy.x >= 0 or abs(enemy.y) >= 0.5):
        return release("front")
    # Keep holding the enemy if the clamp is holding and the enemy is in front
    elif me.weapons["front"]["state"] == "holding" and enemy.x < 0 and abs(enemy.y) < 0.5:
        return None
    else:
        return None

def drive(me, enemy, arena):
    # Desired engagement distance (meters)
    engage_dist = 1.0
    # Compute distance to enemy
    d = distance_to(enemy.x, enemy.y)
    # If we're far, go full ahead
    if d > 2.0:
        return (1.0, 1.0)
    # If we're within engagement distance, back off a bit to avoid clamp
    if d <= engage_dist:
        return (-0.5, -0.5)
    # Otherwise, approach while staying to the side to avoid the front clamp
    bearing = bearing_to(enemy.x, enemy.y)  # degrees, positive = left of heading
    # Turn gently left if enemy is roughly ahead
    if -30 <= bearing <= 30:
        return (0.6, 0.8)   # turn left
    # Turn more left if enemy is on the left side
    if bearing > 30:
        return (0.4, 0.9)
    # Turn right if enemy is on the right side
    if bearing < -30:
        return (0.9, 0.4)
    # Default modest forward drive
    return (0.6, 0.6)

